function traceSlowWorkletsEnabled() {
  'worklet';

  return (
    TRACE_SLOW_WORKLETS ||
    (globalThis as Record<string, any>).__NSRNS_TRACE_SLOW_WORKLETS === true
  );
}

function traceEventsEnabled() {
  'worklet';

  return (
    TRACE_TRANSITION_EVENTS ||
    traceSlowWorkletsEnabled() ||
    (globalThis as Record<string, any>).__NSRNS_TRACE_EVENTS === true
  );
}

