function traceTimestamp() {
  'worklet';

  if (!traceEventsEnabled()) {
    return 0;
  }

  const performanceObject = (globalThis as Record<string, any>).performance;

  if (typeof performanceObject?.now === 'function') {
    return performanceObject.now();
  }

  if (typeof Date?.now === 'function') {
    return Date.now();
  }

  return 0;
}

function lifecycleTimestamp() {
  'worklet';
  const performanceObject = (globalThis as Record<string, any>).performance;

  if (typeof performanceObject?.now === 'function') {
    return performanceObject.now();
  }

  if (typeof Date?.now === 'function') {
    return Date.now();
  }

  return 0;
}

function traceWorkletMessage(message: string) {
  'worklet';

  const globalObject = globalThis as Record<string, any>;
  const buffer = Array.isArray(globalObject.__NSRNS_TRACE_BUFFER)
    ? globalObject.__NSRNS_TRACE_BUFFER
    : [];

  buffer[buffer.length] = message;
  while (buffer.length > 120) {
    buffer.shift();
  }
  globalObject.__NSRNS_TRACE_BUFFER = buffer;

  if (typeof globalObject.TNSLog === 'function') {
    globalObject.TNSLog(message);
  }

  const NSLog = globalObject.NSLog;
  if (typeof NSLog === 'function') {
    try {
      NSLog(message);
    } catch (_error) {
      // Fall back to JS logging below.
    }
  }

  console.warn(message);
}

function traceHitTest(message: string) {
  'worklet';

  if (
    !TRACE_HIT_TESTS &&
    (globalThis as Record<string, any>).__NSRNS_TRACE_HIT_TESTS !== true
  ) {
    return;
  }

  traceWorkletMessage(`[NSRNS_HIT] ${message}`);
}

function traceSlowWorklet(label: string, startedAt: number, details = '') {
  'worklet';

  if (!traceSlowWorkletsEnabled()) {
    return;
  }

  const duration = traceTimestamp() - startedAt;

  if (duration < 16) {
    return;
  }

  traceWorkletMessage(
    `[NSRNS_TRACE ${Math.round(traceTimestamp())}] ${label} ${Math.round(
      duration,
    )}ms${details ? ` ${details}` : ''}`,
  );
}

function traceWorkletEvent(label: string, details = '') {
  'worklet';

  if (!traceEventsEnabled()) {
    return;
  }

  traceWorkletMessage(
    `[NSRNS_TRACE ${Math.round(traceTimestamp())}] ${label}${
      details ? ` ${details}` : ''
    }`,
  );
}

function callWorkletFunction(
  callback: any,
  first?: any,
  second?: any,
  third?: any,
  fourth?: any,
) {
  'worklet';

  if (typeof callback !== 'function') {
    return undefined;
  }

  if (typeof callback.call === 'function') {
    return callback.call(callback, first, second, third, fourth);
  }

  return callback(first, second, third, fourth);
}

