function setNavigationItemLargeTitleText(
  navigationItem: any,
  title: string,
  enabled: boolean,
) {
  'worklet';

  // NATIVESCRIPT_PORT_DEVIATION: iOS 26 exposes UINavigationItem.largeTitle
  // separately from title. Upstream native-stack relies on ObjC/UIKit not
  // materializing that property for regular titles; clear it explicitly in
  // the TS port so a non-large React Navigation title stays centered/small.
  setNativeValueForKey(navigationItem, 'largeTitle', enabled ? title : null);
}

