  const includeOwnFrame = depth > 0 && isVisible && (hasUserPayload || isLeaf);
  let maxRight = includeOwnFrame ? absoluteX + width : 0;
  let maxBottom = includeOwnFrame ? absoluteY + height : 0;
  let hasContent = includeOwnFrame;

  for (let index = 0; index < count && index < 48; index += 1) {
    const subview = arrayItem(subviews, index);

    if (!subview || subview.hidden === true || (subview.alpha ?? 1) <= 0.01) {
      continue;
    }

    const extent = hostedSubviewVisibleContentExtent(
      subview,
      absoluteX,
      absoluteY,
      visitedViews,
      depth + 1,
    );

    if (!extent.hasContent) {
      continue;
    }

    hasContent = true;
    maxRight = Math.max(maxRight, extent.maxRight);
    maxBottom = Math.max(maxBottom, extent.maxBottom);
  }

  return { hasContent, maxBottom, maxRight };
