    const subviewFrame = subview.frame;
    const originX = Number(subviewFrame?.origin?.x ?? subviewFrame?.x ?? 0);
    const originY = Number(subviewFrame?.origin?.y ?? subviewFrame?.y ?? 0);
    const subviewSize = headerSubviewMeasuredDescendantSize(subview, depth + 1);

